    /// <summary>
    /// Sends a code to verify an email address to be added to a user's Telegram Passport
    /// </summary>
    public Task<TdLib.TdApi.Objects.EmailAddressAuthenticationCodeInfo> SendEmailAddressVerificationCodeAsync(string emailAddress = default)
    {

           using var activity =  StartCallActivity("SendEmailAddressVerificationCodeAsync", typeof(SendEmailAddressVerificationCode).FullName ?? "SendEmailAddressVerificationCodeAsync");

           try
           {
             return client.SendEmailAddressVerificationCodeAsync(emailAddress);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
